<?php
namespace App\Payments\Gateways\GoBiz;
final class GoBizJournal { public function fetch():array{$url=$_ENV['GOBIZ_JOURNAL_URL']??'';$token=$_ENV['GOBIZ_TOKEN']??'';if(!$url||!$token)return [];$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Accept: application/json','Authorization: Bearer '.$token],CURLOPT_TIMEOUT=>25]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$j=json_decode((string)$raw,true);if($code>=400||!is_array($j))throw new \RuntimeException('GoBiz journal gagal HTTP '.$code);return $j['data']??$j;} }
